use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclstruct! {
# [doc = " An indexed multi-map that preserves insertion order while permitting both *O*(log *n*) lookup of"] # [doc = " an item by key and *O*(1) lookup by index."] # [doc = ""] # [doc = " This data structure is a hybrid of an [`IndexVec`] and a [`SortedMap`]. Like `IndexVec`,"] # [doc = " `SortedIndexMultiMap` assigns a typed index to each item while preserving insertion order."] # [doc = " Like `SortedMap`, `SortedIndexMultiMap` has efficient lookup of items by key. However, this"] # [doc = " is accomplished by sorting an array of item indices instead of the items themselves."] # [doc = ""] # [doc = " Unlike `SortedMap`, this data structure can hold multiple equivalent items at once, so the"] # [doc = " `get_by_key` method and its variants return an iterator instead of an `Option`. Equivalent"] # [doc = " items will be yielded in insertion order."] # [doc = ""] # [doc = " Unlike a general-purpose map like `BTreeSet` or `HashSet`, `SortedMap` and"] # [doc = " `SortedIndexMultiMap` require *O*(*n*) time to insert a single item. This is because we may need"] # [doc = " to insert into the middle of the sorted array. Users should avoid mutating this data structure"] # [doc = " in-place."] # [doc = ""] # [doc = " [`SortedMap`]: super::SortedMap"] # [derive (Clone , Debug)] pub struct SortedIndexMultiMap < I : Idx , K , V > { # [doc = " The elements of the map in insertion order."] items : IndexVec < I , (K , V) > , # [doc = " Indices of the items in the set, sorted by the item's key."] idx_sorted_by_item_key : Vec < I > , }
}